/* Theme Toggle - Light/Dark mode switcher. Default is dark; light only when the OS prefers light (or a saved choice). */const themeToggle = document.querySelector('.theme-toggle');const html = document.documentElement;function resolveTheme() { const saved = localStorage.getItem('theme-preference'); if (saved) { return saved; } if (window.matchMedia('(prefers-color-scheme: light)').matches) { return 'light'; } return 'dark';}function updateThemeIcon() { const sunIcon = document.querySelector('.icon-sun'); const moonIcon = document.querySelector('.icon-moon'); const currentTheme = html.getAttribute('data-theme'); if (currentTheme === 'dark') { if (sunIcon) sunIcon.setAttribute('hidden', ''); if (moonIcon) moonIcon.removeAttribute('hidden'); updateFavicon('dark'); } else { if (sunIcon) sunIcon.removeAttribute('hidden'); if (moonIcon) moonIcon.setAttribute('hidden', ''); updateFavicon('light'); }}function updateFavicon(theme) { const faviconLink = document.querySelector('link[rel="icon"]'); if (faviconLink) { faviconLink.href = theme === 'dark' ? 'assets/icons/favicon-dark.svg' : 'assets/icons/favicon.svg'; }}if (themeToggle) { themeToggle.addEventListener('click', () => { const currentTheme = html.getAttribute('data-theme'); const newTheme = currentTheme === 'dark' ? 'light' : 'dark'; html.setAttribute('data-theme', newTheme); localStorage.setItem('theme-preference', newTheme); updateThemeIcon(); });}function initTheme() { html.setAttribute('data-theme', resolveTheme());}if (document.readyState === 'loading') { document.addEventListener('DOMContentLoaded', () => { initTheme(); updateThemeIcon(); });} else { initTheme(); updateThemeIcon();}window.matchMedia('(prefers-color-scheme: light)').addEventListener('change', (e) => { if (!localStorage.getItem('theme-preference')) { html.setAttribute('data-theme', e.matches ? 'light' : 'dark'); updateThemeIcon(); }});